def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'

    # Count opponent and own behavior
    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    cc = 0
    dd = 0
    cd = 0
    dc = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'D' and b == 'D':
            dd += 1
        elif a == 'C' and b == 'D':
            cd += 1
        else:
            dc += 1

    last_me, last_opp = history[-1]
    remaining = 100 - n

    # Detect sustained defector: once confident, always defect
    if n >= 8:
        last8_opp = [b for a, b in history[-8:]]
        if last8_opp.count('D') >= 7:
            return 'D'

    # Detect mostly-defect early and punish hard
    if n >= 6 and opp_d >= n - 1:
        return 'D'

    # Detect always-cooperator: exploit but keep them cooperating
    if opp_d == 0 and n >= 4:
        # Probe occasionally; if they still cooperate, keep exploiting mildly
        if remaining <= 3:
            return 'D'
        if n >= 20 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # If opponent has very low defection rate and we haven't been punishing,
    # cooperate to build mutual CC, but take some endgame DC.
    if n >= 10 and opp_d * 5 <= n:
        if remaining <= 2:
            return 'D'
        # Small periodic probe to test for exploitability
        if n in (25, 50, 75) and rng.random() < 0.5:
            return 'D'
        return 'C'

    # If we just defected and opponent still cooperated, they may be forgiving.
    # Reduce exploitation to preserve cooperation unless they look like a pure cooperator.
    if last_me == 'D' and last_opp == 'C':
        if opp_d == 0:
            return 'D' if remaining <= 4 else 'C'
        # Otherwise return to cooperation
        return 'C'

    # If opponent defected last round after we cooperated: retaliate once
    if last_opp == 'D' and last_me == 'C':
        # But forgive if opponent is generally cooperative and this is a rare defection
        if n >= 4 and opp_d <= max(1, n // 12):
            return 'C'
        return 'D'

    # If opponent defected after we defected, keep mutual defection short:
    # try to restore cooperation if opponent has shown cooperation recently.
    if last_opp == 'D' and last_me == 'D':
        if n >= 4 and opp_d <= n // 2:
            recent_opp = [b for a, b in history[-4:]]
            if recent_opp.count('C') >= 1:
                return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If they've been moderately cooperative, cooperate but occasionally probe.
    if opp_d * 3 <= n:
        if remaining <= 3:
            return 'D'
        # Very rare probing
        if n >= 15 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Mixed opponent: use a forgiving tit-for-tat with occasional defection
    if opp_d * 2 <= n:
        if last_opp == 'C':
            return 'C' if rng.random() < 0.9 else 'D'
        return 'D'

    # Opponent mostly defects: defect with occasional cooperation to probe
    if last_opp == 'C':
        return 'D' if rng.random() < 0.8 else 'C'
    return 'D'
